internal interface ISamplerBuilder {
    /// <summary>
    /// Constrain output to a grammar, given as either Lark or GBNF.
    /// </summary>
    SamplerBuilder ConstrainWithGrammar(string @grammar);
    /// <summary>
    /// Constrain output to a JSON schema, given as a JSON string.
    /// </summary>
    SamplerBuilder ConstrainWithJsonSchema(string @schema);
    /// <summary>
    /// Constrain output to a regular expression.
    /// </summary>
    SamplerBuilder ConstrainWithRegex(string @pattern);
    /// <summary>
    /// Sample from the probability distribution (weighted random selection).
    /// </summary>
    SamplerConfig Dist();
    /// <summary>
    /// DRY (Don't Repeat Yourself) sampler to reduce repetition.
    /// </summary>
    SamplerBuilder Dry(float @multiplier, float @base, int @allowedLength, int @penaltyLastN, string[] @seqBreakers);
    /// <summary>
    /// Apply dynamic temperature scaling (a.k.a. entropy) described in the paper
    /// <https://arxiv.org/abs/2309.02772>.
    ///
    /// Args:
    /// temperature: Temperature value (lower = more focused, higher = more random)
    /// delta: Dynamic temperature range. The final temperature will be in the range of `[temperature - delta; temperature + delta]`.
    /// exponent: Temperature is calculated as `entropy^exponent` (bounded by the range above)
    /// </summary>
    SamplerBuilder DynamicTemperature(float @temperature, float @delta, float @exponent);
    /// <summary>
    /// Always select the most probable token (deterministic).
    /// </summary>
    SamplerConfig Greedy();
    /// <summary>
    /// Constrain output to a JSON object of any shape. Use
    /// `constrain_with_json_schema()` to pin down the structure too.
    /// </summary>
    SamplerBuilder Json();
    /// <summary>
    /// Modify the likelihood of specific tokens.
    ///
    /// Args:
    /// biases: Mapping from token ID to its bias.
    /// The bias modifies the likelihood of the token being selected
    /// (`>0.0` means higher probability of the token being selected).
    /// Use `-Infinity` to ban a token.
    /// </summary>
    SamplerBuilder LogitBias(Dictionary<int, float> @biases);
    /// <summary>
    /// Keep tokens with probability above min_p * (probability of most likely token).
    /// </summary>
    SamplerBuilder MinP(float @minP, uint @minKeep);
    /// <summary>
    /// Use Mirostat v1 algorithm for perplexity-controlled sampling.
    /// </summary>
    SamplerConfig MirostatV1(float @tau, float @eta, int @m);
    /// <summary>
    /// Use Mirostat v2 algorithm for perplexity-controlled sampling.
    /// </summary>
    SamplerConfig MirostatV2(float @tau, float @eta);
    /// <summary>
    /// Apply repetition penalties to discourage repeated tokens.
    /// </summary>
    SamplerBuilder Penalties(int @penaltyLastN, float @penaltyRepeat, float @penaltyFreq, float @penaltyPresent);
    /// <summary>
    /// Set the RNG seed used by random samplers (`dist`, `mirostat_v1`, `mirostat_v2`, `xtc`).
    /// `greedy` ignores it. If unset, a default seed is used.
    /// </summary>
    SamplerBuilder Seed(uint @seed);
    /// <summary>
    /// Apply temperature scaling to the probability distribution.
    /// </summary>
    SamplerBuilder Temperature(float @temperature);
    /// <summary>
    /// Keep only the top K most probable tokens.
    /// </summary>
    SamplerBuilder TopK(int @topK);
    /// <summary>
    /// Top-nσ sampling as described in academic paper "Top-nσ: Not All Logits Are You Need"
    /// <https://arxiv.org/pdf/2411.07641>
    ///
    /// Args:
    /// n: Number of standard deviations from the mean to include in sampling.
    /// </summary>
    SamplerBuilder TopNSigma(float @n);
    /// <summary>
