/// <summary>
/// How a chat forgets old turns when its context is full. A turn is a user
/// message and everything up to the next one; system messages are always kept.
/// </summary>
/// <param name="Enabled">
/// `false` disables shifting, so a full context is an error instead.
/// </param>
/// <param name="KeepFirstTurns">
/// Turns always kept at the start of the history.
/// </param>
/// <param name="KeepLastTurns">
/// Turns always kept at the end of the history; at least 1.
/// </param>
/// <param name="Target">
/// Size the history is shrunk to. `null` means half the context size.
/// </param>
internal record ContextShiftOptions (
    /// <summary>
    /// `false` disables shifting, so a full context is an error instead.
    /// </summary>
    bool Enabled = true, 
    /// <summary>
    /// Turns always kept at the start of the history.
    /// </summary>
    uint KeepFirstTurns = 1u, 
    /// <summary>
    /// Turns always kept at the end of the history; at least 1.
    /// </summary>
    uint KeepLastTurns = 2u, 
    /// <summary>
    /// Size the history is shrunk to. `null` means half the context size.
    /// </summary>
    ShiftTarget? Target = null
) {
}

class FfiConverterTypeContextShiftOptions: FfiConverterRustBuffer<ContextShiftOptions> {
    public static FfiConverterTypeContextShiftOptions INSTANCE = new FfiConverterTypeContextShiftOptions();

    public override ContextShiftOptions Read(BigEndianStream stream) {
        return new ContextShiftOptions(
            Enabled: FfiConverterBoolean.INSTANCE.Read(stream),
