            KeepLastTurns: FfiConverterUInt32.INSTANCE.Read(stream),
            Target: FfiConverterOptionalTypeShiftTarget.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(ContextShiftOptions value) {
        return 0
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.Enabled)
            + FfiConverterUInt32.INSTANCE.AllocationSize(value.KeepFirstTurns)
            + FfiConverterUInt32.INSTANCE.AllocationSize(value.KeepLastTurns)
            + FfiConverterOptionalTypeShiftTarget.INSTANCE.AllocationSize(value.Target);
    }

    public override void Write(ContextShiftOptions value, BigEndianStream stream) {
            FfiConverterBoolean.INSTANCE.Write(value.Enabled, stream);
            FfiConverterUInt32.INSTANCE.Write(value.KeepFirstTurns, stream);
            FfiConverterUInt32.INSTANCE.Write(value.KeepLastTurns, stream);
