    /// Maximum draft tokens proposed per speculative step (llama.cpp `n_max`).
    /// Higher values draft more per decode; returns diminish past ~4–6.
    /// </summary>
    uint KMax = 3u, 
    /// <summary>
    /// Minimum draft-token probability the drafter will propose (llama.cpp
    /// `p_min`). `0.0` accepts all proposals; raise it to skip low-confidence
    /// drafts.
    /// </summary>
    float PMin = 0.0f
) {
}

class FfiConverterTypeMtpConfig: FfiConverterRustBuffer<MtpConfig> {
    public static FfiConverterTypeMtpConfig INSTANCE = new FfiConverterTypeMtpConfig();

    public override MtpConfig Read(BigEndianStream stream) {
        return new MtpConfig(
            KMax: FfiConverterUInt32.INSTANCE.Read(stream),
            PMin: FfiConverterFloat.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(MtpConfig value) {
        return 0
            + FfiConverterUInt32.INSTANCE.AllocationSize(value.KMax)
            + FfiConverterFloat.INSTANCE.AllocationSize(value.PMin);
    }

    public override void Write(MtpConfig value, BigEndianStream stream) {
            FfiConverterUInt32.INSTANCE.Write(value.KMax, stream);
            FfiConverterFloat.INSTANCE.Write(value.PMin, stream);
    }
}



